# Long Lost Cousin: candidate puzzles. opts = [(key, rank)], rank 0 = closest relative of the subject among the three,
# then 1, then 2. Two options with rank 1 = they are each other's closest relatives and equally far from the subject.
# group: mammals | birds | reptiles (with amphibians and dinosaurs) | sea (fish and sea life) | small (insects, spiders, worms) | plants (and fungi)
C = [
# ---------------- mammals
("M01", "hippo", [("whale",0),("pig",1),("rhino",2)], "mammals", "Hippos' closest living relatives are whales and dolphins (cetaceans); together they form Whippomorpha. Pigs are more distant even-toed ungulates. Rhinos are odd-toed ungulates, outside the even-toed group."),
("M02", "elephant", [("manatee",0),("rhino",1),("hippo",1)], "mammals", "Elephants' closest living relatives are manatees and dugongs (sea cows) and hyraxes (Paenungulata, within Afrotheria). Rhinos and hippos are both hoofed mammals of Laurasiatheria, closer to each other than either is to elephants."),
("M03", "hyrax", [("elephant",0),("guinea_pig",1),("rabbit",1)], "mammals", "The hyrax looks like a rodent but its closest living relatives are elephants and sea cows (Paenungulata). Guinea pigs (rodents) and rabbits (lagomorphs) are each other's closest relatives (Glires)."),
("M04", "hyena", [("cat",0),("dog",1),("bear",1)], "mammals", "Hyenas are feliforms: closer to cats (and mongooses) than to dogs. Dogs and bears are both caniforms, closer to each other than to hyenas."),
("M05", "red_panda", [("raccoon",0),("giant_panda",1),("cat",2)], "mammals", "The red panda is not a bear: it belongs to Musteloidea with raccoons, weasels and skunks. The giant panda is a bear (Ursidae), a more distant caniform. Cats are feliforms, further still."),
("M06", "giant_panda", [("polar_bear",0),("red_panda",1),("raccoon",1)], "mammals", "The giant panda is a true bear (Ursidae), so the polar bear is its closest relative here. Red pandas and raccoons are both musteloids, closer to each other than to bears."),
("M07", "koala", [("wombat",0),("kangaroo",1),("bear",2)], "mammals", "The koala's closest living relatives are wombats (Vombatiformes). Kangaroos are more distant marsupials of the same order (Diprotodontia). Bears are placental mammals, unrelated."),
("M08", "dolphin", [("cow",0),("seal",1),("shark",2)], "mammals", "Dolphins (cetaceans) evolved from even-toed hoofed mammals, so the cow is a closer relative than the seal (a carnivoran). Sharks are fish, far more distant."),
("M09", "seal", [("dog",0),("dolphin",1),("manatee",2)], "mammals", "Seals are carnivorans (caniforms), so dogs are closer relatives than dolphins (cetaceans). Manatees belong to Afrotheria with elephants, further away still. Seals, dolphins and manatees went back to the sea independently."),
("M10", "bat", [("horse",0),("mouse",1),("monkey",1)], "mammals", "Bats are not flying mice: bats belong to Laurasiatheria with horses, cats, dogs and whales. Mice (rodents) and monkeys (primates) both belong to Euarchontoglires and are closer to each other than to bats."),
("M11", "human", [("chimp",0),("gorilla",1),("orangutan",2)], "mammals", "Humans' closest living relatives are chimpanzees (and bonobos), then gorillas, then orangutans."),
("M12", "shrew", [("hedgehog",0),("mouse",1),("rabbit",1)], "mammals", "Shrews look like mice but are not rodents: they belong to Eulipotyphla with hedgehogs and moles. Mice and rabbits are each other's closest relatives here (Glires)."),
("M13", "thylacine", [("kangaroo",0),("wolf",1),("cat",1)], "mammals", "The thylacine (Tasmanian tiger or Tasmanian wolf) was a marsupial, so the kangaroo is a closer relative than the wolf or the tiger, which are placental carnivorans. Its dog-like look is convergent evolution."),
("M14", "sugar_glider", [("koala",0),("flying_squirrel",1),("bat",1)], "mammals", "The sugar glider is a marsupial (order Diprotodontia, like koalas and kangaroos). Flying squirrels (rodents) and bats are placental mammals; gliding evolved separately (convergent evolution)."),
("M15", "armadillo", [("sloth",0),("pangolin",1),("hedgehog",1)], "mammals", "Armadillos' closest living relatives are sloths and anteaters (Xenarthra). Pangolins, though armoured, are not related to armadillos: pangolins and hedgehogs both belong to Laurasiatheria."),
("M16", "pangolin", [("cat",0),("armadillo",1),("anteater",1)], "mammals", "Pangolins' closest living relatives are the carnivorans (cats, dogs, bears); together they form Ferae. Armadillos and anteaters are xenarthrans, closer to each other."),
("M17", "anteater", [("sloth",0),("pangolin",1),("echidna",2)], "mammals", "Anteaters' closest living relatives are sloths (order Pilosa). The pangolin (scaly anteater) is a distant placental mammal. The echidna (spiny anteater) is an egg-laying monotreme, further still."),
("M18", "aardvark", [("elephant",0),("pig",1),("kangaroo",2)], "mammals", "The aardvark belongs to Afrotheria, the group that includes elephants, sea cows and hyraxes, so the elephant is a closer relative than the pig. Kangaroos are marsupials, further still."),
("M19", "horse", [("rhino",0),("cow",1),("camel",1)], "mammals", "Horses are odd-toed ungulates (Perissodactyla) together with rhinos and tapirs. Cows and camels are even-toed ungulates (Artiodactyla), closer to each other than to horses."),
("M20", "camel", [("llama",0),("cow",1),("horse",2)], "mammals", "Camels and llamas belong to the same family (Camelidae). Giraffes are other even-toed ungulates. Horses are odd-toed ungulates, further away."),
("M21", "giraffe", [("okapi",0),("camel",1),("zebra",2)], "mammals", "The okapi is the giraffe's only living close relative (family Giraffidae), despite its zebra-like stripes. Camels are other even-toed ungulates. Zebras are odd-toed ungulates (horses)."),
("M22", "otter", [("weasel",0),("seal",1),("beaver",2)], "mammals", "Otters belong to the weasel family (Mustelidae). Seals are other carnivorans. Beavers are rodents."),
("M23", "beaver", [("mouse",0),("otter",1),("platypus",2)], "mammals", "Beavers are rodents, like mice. Otters are placental carnivorans. The platypus is an egg-laying monotreme, the most distant."),
("M24", "echidna", [("platypus",0),("hedgehog",1),("porcupine",1)], "mammals", "The echidna's closest living relative is the platypus: both are monotremes, mammals that lay eggs. Hedgehogs and porcupines are placental mammals, closer to each other than to the echidna; spines evolved independently."),
("M25", "mouse", [("human",0),("shrew",1),("kangaroo",2)], "mammals", "Mice (rodents) and humans (primates) both belong to Euarchontoglires, so a human is a closer relative of the mouse than a shrew is (shrews belong to Laurasiatheria). Kangaroos are marsupials."),
("M26", "meerkat", [("cat",0),("weasel",1),("prairie_dog",2)], "mammals", "Meerkats are mongooses (Herpestidae), feliform carnivorans, closer to cats than to weasels (caniforms). Prairie dogs are rodents."),
("M27", "guinea_pig", [("capybara",0),("mouse",1),("rabbit",2)], "mammals", "The capybara is in the same family as guinea pigs (Caviidae). Hamsters are more distant rodents. Rabbits are lagomorphs, not rodents."),
("M28", "narwhal", [("beluga",0),("walrus",1),("marlin",2)], "mammals", "The narwhal and the beluga are the only two living members of the family Monodontidae. The walrus is a carnivoran (pinniped). The swordfish is a fish."),
("M29", "orca", [("dolphin",0),("humpback",1),("great_white",2)], "mammals", "The orca (killer whale) is the largest member of the dolphin family (Delphinidae). The humpback is a baleen whale, a more distant cetacean. The great white shark is a fish."),
("M30", "mammoth", [("asian_elephant",0),("african_elephant",1),("mastodon",2)], "mammals", "Ancient DNA shows woolly mammoths were more closely related to Asian elephants than to African elephants. Mastodons belong to a separate, much older family (Mammutidae)."),
("M31", "tapir", [("horse",0),("pig",1),("elephant",2)], "mammals", "Tapirs are odd-toed ungulates (Perissodactyla) with horses and rhinos. Pigs are even-toed ungulates. Elephants belong to Afrotheria, further away."),
("M32", "walrus", [("sea_lion",0),("seal",1),("manatee",2)], "mammals", "Among pinnipeds, the walrus is more closely related to sea lions and fur seals (eared seals) than to true (earless) seals. Manatees are not pinnipeds at all (they are sea cows, relatives of elephants)."),
("M33", "zebra", [("horse",0),("rhino",1),("camel",2)], "mammals", "Zebras and horses are the same genus (Equus). Rhinos are other odd-toed ungulates. Giraffes are even-toed ungulates."),
("M34", "deer", [("cow",0),("pig",1),("horse",2)], "mammals", "Deer and giraffes are both ruminants (Pecora). Pigs are other even-toed ungulates. Horses are odd-toed ungulates, so a deer is closer to a pig than to a horse."),
("M35", "porcupine", [("guinea_pig",0),("hedgehog",1),("echidna",2)], "mammals", "Porcupines are rodents of the suborder Hystricomorpha, like guinea pigs and capybaras. Hedgehogs are placental mammals of another order. Echidnas are egg-laying monotremes."),
# ---------------- birds
("B01", "falcon", [("parrot",0),("eagle",1),("heron",2)], "birds", "Genome studies show falcons are more closely related to parrots and songbirds (Australaves) than to hawks and eagles (Accipitriformes). Herons are water birds outside the land-bird group (Telluraves)."),
("B02", "flamingo", [("grebe",0),("stork",1),("heron",1)], "birds", "The flamingo's closest living relatives are the grebes (clade Mirandornithes). Storks and herons, which look similar, are closer to each other (both in Aequornithes)."),
("B03", "penguin", [("albatross",0),("puffin",1),("duck",2)], "birds", "Penguins' closest living relatives are the tube-nosed seabirds: albatrosses and petrels (Procellariiformes). Puffins (auks) look like penguins but belong to the shorebird order (Charadriiformes). Ducks belong to the fowl (Galloanserae), outside Neoaves."),
("B04", "swift", [("hummingbird",0),("swallow",1),("falcon",1)], "birds", "Swifts' closest relatives are hummingbirds (order Apodiformes). Swallows look like swifts but are songbirds (passerines), and passerines are closer to falcons and parrots (Australaves)."),
("B05", "kiwi", [("elephant_bird",0),("moa",1),("ostrich",2)], "birds", "Ancient DNA (Mitchell et al. 2014) showed the kiwi's closest relatives were the extinct elephant birds of Madagascar, not the moa of New Zealand. The ostrich is the most distant of these ratites."),
("B06", "duck", [("chicken",0),("coot",1),("penguin",1)], "birds", "Ducks (waterfowl, Anseriformes) and chickens (landfowl, Galliformes) are each other's closest relatives: together they form the fowl, Galloanserae. Coots (rails) and penguins both belong to Neoaves."),
("B07", "dodo", [("pigeon",0),("turkey",1),("ostrich",2)], "birds", "The dodo was a giant flightless pigeon (family Columbidae). Turkeys are fowl. Ostriches belong to the palaeognaths, the most distant branch of living birds."),
("B08", "toucan", [("woodpecker",0),("hornbill",1),("parrot",2)], "birds", "Toucans belong to the order Piciformes with woodpeckers. Hornbills look similar (big bill) but belong to a different order (Bucerotiformes); the resemblance is convergent. Parrots are further away."),
("B09", "ostrich", [("emu",0),("flamingo",1),("crane",1)], "birds", "Ostriches and emus are both palaeognaths (ratites). Flamingos and cranes both belong to Neoaves, closer to each other than to the ostrich."),
("B10", "swallow", [("sparrow",0),("parrot",1),("swift",2)], "birds", "Swallows are songbirds (passerines), like sparrows. Parrots are the passerines' closest relatives (Psittacopasserae). Swifts look like swallows but are relatives of hummingbirds, far away on the bird tree."),
# ---------------- reptiles, amphibians, dinosaurs
("R01", "trex", [("chicken",0),("crocodile",1),("komodo",2)], "reptiles", "Birds are living dinosaurs (theropods), so the chicken is T. rex's closest living relative here. Crocodiles are the next closest (archosaurs). The Komodo dragon is a lizard (lepidosaur), more distant."),
("R02", "crocodile", [("eagle",0),("lizard",1),("salamander",2)], "reptiles", "Crocodiles' closest living relatives are birds (both are archosaurs), not lizards. Salamanders are amphibians, more distant."),
("R03", "turtle", [("crocodile",0),("lizard",1),("frog",2)], "reptiles", "Genome studies place turtles as the sister group of archosaurs (crocodiles and birds), so a turtle is closer to a crocodile than to a lizard. Frogs are amphibians."),
("R04", "pterodactyl", [("eagle",0),("crocodile",1),("bat",2)], "reptiles", "Pterosaurs were flying reptiles, the closest relatives of dinosaurs (and birds are dinosaurs), so a bird is closer than a crocodile. Bats are mammals; flight evolved independently."),
("R05", "ichthyosaur", [("lizard",0),("dolphin",1),("shark",2)], "reptiles", "Ichthyosaurs were marine reptiles, so a lizard is a closer relative than a dolphin (a mammal) or a shark (a fish). Their dolphin-like shape is a classic case of convergent evolution."),
("R06", "dimetrodon", [("dog",0),("trex",1),("crocodile",1)], "reptiles", "Dimetrodon was not a dinosaur: it was a synapsid, more closely related to mammals than to dinosaurs or any living reptile. T. rex and crocodiles are both archosaurs."),
("R07", "axolotl", [("frog",0),("lizard",1),("eel",2)], "reptiles", "The axolotl is a salamander, an amphibian, so the frog is its closest relative here. Lizards are reptiles (amniotes). Eels are ray-finned fish."),
("R08", "komodo", [("snake",0),("crocodile",1),("salamander",2)], "reptiles", "Monitor lizards such as the Komodo dragon are closely related to snakes (both squamates, in Toxicofera). Crocodiles are archosaurs, closer to birds. Salamanders are amphibians."),
("R09", "snake", [("iguana",0),("eel",1),("earthworm",2)], "reptiles", "Snakes are squamate reptiles, the same order as lizards such as iguanas. Eels are fish; earthworms are annelids."),
("R10", "triceratops", [("chicken",0),("crocodile",1),("rhino",2)], "reptiles", "Triceratops was a dinosaur, so birds (living dinosaurs) are its closest living relatives, then crocodiles. The rhino is a mammal; its horns are convergent."),
("R11", "stegosaurus", [("triceratops",0),("trex",1),("crocodile",2)], "reptiles", "Stegosaurus and Triceratops were both ornithischian dinosaurs. T. rex was a saurischian (theropod) dinosaur. Crocodiles are not dinosaurs."),
("R12", "velociraptor", [("eagle",0),("triceratops",1),("crocodile",2)], "reptiles", "Velociraptor was a feathered dromaeosaur, among the closest dinosaur relatives of birds. Triceratops was a more distant dinosaur. Crocodiles are not dinosaurs."),
# ---------------- fish and sea life
("F01", "shark", [("ray",0),("tuna",1),("dolphin",1)], "sea", "Sharks' closest relatives are rays and skates (cartilaginous fish). A tuna is a bony fish, and bony fish are more closely related to land vertebrates such as dolphins than to sharks."),
("F02", "lungfish", [("cow",0),("salmon",1),("shark",2)], "sea", "Lungfish are the closest living relatives of the four-limbed animals (tetrapods), so a lungfish is more closely related to a cow than to a salmon. Sharks are more distant still."),
("F03", "whale_shark", [("great_white",0),("whale",1),("tuna",1)], "sea", "The whale shark is a shark, a cartilaginous fish, not a whale. Whales (mammals) and tuna (bony fish) are both bony vertebrates, closer to each other than to sharks."),
("F04", "starfish", [("human",0),("octopus",1),("crab",1)], "sea", "Starfish (echinoderms) are deuterostomes, like vertebrates, so a starfish is more closely related to a human than to an octopus or a crab (both protostomes)."),
("F05", "octopus", [("snail",0),("starfish",1),("jellyfish",2)], "sea", "The octopus is a mollusc, like snails. Starfish are echinoderms, other bilaterian animals. Jellyfish (cnidarians) are outside the bilaterians."),
("F06", "jellyfish", [("coral",0),("octopus",1),("sponge",2)], "sea", "Jellyfish and corals are both cnidarians. Cnidarians are closer to bilaterian animals such as the octopus than to sponges."),
("F07", "horseshoe_crab", [("spider",0),("crab",1),("lobster",1)], "sea", "Horseshoe crabs are not crabs: they are chelicerates, more closely related to spiders and scorpions than to crabs and lobsters (crustaceans)."),
("F08", "barnacle", [("crab",0),("mussel",1),("snail",1)], "sea", "Barnacles are crustaceans, related to crabs and shrimp, not molluscs like mussels and snails."),
("F09", "seahorse", [("tuna",0),("shark",1),("squid",2)], "sea", "The seahorse is a bony ray-finned fish, like tuna. Sharks are cartilaginous fish. Squid are molluscs."),
("F10", "sea_urchin", [("starfish",0),("hedgehog",1),("jellyfish",2)], "sea", "Sea urchins and starfish are both echinoderms. Echinoderms are deuterostomes, closer to vertebrates (such as the hedgehog) than to jellyfish."),
("F11", "eel", [("salmon",0),("snake",1),("lamprey",2)], "sea", "Eels are bony ray-finned fish (teleosts), like salmon. Bony fish are closer to land vertebrates such as snakes than to lampreys, which are jawless fish and only look like eels."),
("F12", "sea_cucumber", [("starfish",0),("slug",1),("earthworm",1)], "sea", "Sea cucumbers are echinoderms, like starfish. Slugs (molluscs) and earthworms (annelids) are both lophotrochozoans, closer to each other."),
# ---------------- insects and other small creatures
("I01", "termite", [("cockroach",0),("ant",1),("wasp",1)], "small", "Termites are not related to ants: they are social cockroaches (order Blattodea). Ants and wasps are each other's close relatives (Hymenoptera)."),
("I02", "ant", [("bee",0),("termite",1),("spider",2)], "small", "Ants belong to Hymenoptera with bees and wasps. Termites are other insects (cockroach relatives). Spiders are arachnids, not insects."),
("I03", "tick", [("spider",0),("flea",1),("louse",1)], "small", "Ticks are arachnids, like spiders, not insects. Fleas and lice are insects."),
("I04", "firefly", [("ladybird",0),("housefly",1),("dragonfly",2)], "small", "Fireflies are beetles (Coleoptera), like ladybirds, not flies. Flies are other insects with complete metamorphosis (Holometabola). Dragonflies are a much older branch of insects."),
("I05", "woodlouse", [("shrimp",0),("beetle",1),("millipede",2)], "small", "Woodlice (pill bugs) are crustaceans (isopods), relatives of shrimp and crabs. Insects are closer to crustaceans (Pancrustacea) than millipedes are."),
("I06", "scorpion", [("spider",0),("lobster",1),("centipede",1)], "small", "Scorpions are arachnids, like spiders. Lobsters (crustaceans) and centipedes (myriapods) both belong to Mandibulata, closer to each other than to arachnids."),
("I07", "mantis", [("cockroach",0),("grasshopper",1),("dragonfly",2)], "small", "Praying mantises' closest relatives are cockroaches and termites (superorder Dictyoptera). Grasshoppers are more distant. Dragonflies are an ancient separate branch."),
("I08", "butterfly", [("moth",0),("bee",1),("dragonfly",2)], "small", "Butterflies and moths form one order (Lepidoptera). Bees are other insects with complete metamorphosis. Dragonflies are an ancient separate branch."),
("I09", "centipede", [("millipede",0),("beetle",1),("earthworm",2)], "small", "Centipedes and millipedes are both myriapods. Beetles are other arthropods. Earthworms are annelids, not arthropods."),
("I10", "slug", [("octopus",0),("earthworm",1),("centipede",2)], "small", "Slugs are molluscs, like the octopus. Earthworms (annelids) are, with molluscs, lophotrochozoans. Centipedes are arthropods (ecdysozoans), more distant."),
("I11", "earthworm", [("leech",0),("centipede",1),("snake",2)], "small", "Earthworms and leeches are both annelids (Clitellata). Centipedes are arthropods, other protostomes. Snakes are vertebrates (deuterostomes), the most distant."),
("I12", "flea", [("housefly",0),("louse",1),("tick",2)], "small", "Fleas are insects with complete metamorphosis, related to scorpionflies and true flies. Lice are more distant insects. Ticks are arachnids."),
("I13", "bee", [("wasp",0),("housefly",1),("dragonfly",2)], "small", "Bees evolved from wasps (Hymenoptera). Flies are other insects with complete metamorphosis. Dragonflies are an ancient separate branch."),
# ---------------- plants and fungi
("P01", "mushroom", [("human",0),("moss",1),("oak",1)], "plants", "Fungi are more closely related to animals than to plants (fungi and animals are both opisthokonts). Moss and oak are both plants."),
("P02", "peanut", [("pea",0),("walnut",1),("pine",2)], "plants", "The peanut is a legume (family Fabaceae), like peas and beans, not a true nut. Walnut is another flowering plant. Pines are conifers (gymnosperms), the most distant."),
("P03", "tomato", [("potato",0),("chili",1),("apple",2)], "plants", "Tomato and potato are in the same genus (Solanum). Chili peppers are in the same family (Solanaceae, nightshades). Cucumbers belong to another family and order."),
("P04", "strawberry", [("rose",0),("apple",1),("tomato",2)], "plants", "Strawberries belong to the rose family (Rosaceae), in the same subfamily as roses (Rosoideae); apples are in the same family but another subfamily. Tomatoes are nightshades."),
("P05", "almond", [("peach",0),("apple",1),("walnut",2)], "plants", "The almond is in the same genus as the peach (Prunus). Apples are in the same family (Rosaceae). Walnuts belong to another order."),
("P06", "cashew", [("mango",0),("peanut",1),("walnut",1)], "plants", "The cashew is in the same family as the mango (Anacardiaceae, which also includes pistachio and poison ivy). Peanut and walnut both belong to the nitrogen-fixing clade of rosids."),
("P07", "banana", [("ginger",0),("palm",1),("apple",2)], "plants", "Bananas belong to the order Zingiberales, with ginger. Palms are other monocots. Apples are eudicots."),
("P08", "cocoa", [("cotton",0),("coffee",1),("tea",1)], "plants", "The cocoa tree is in the mallow family (Malvaceae), with cotton, okra and hibiscus. Coffee and tea are both asterids."),
("P09", "cactus", [("beet",0),("aloe",1),("pineapple",1)], "plants", "Cacti belong to the order Caryophyllales, with beetroot, spinach and carnations. Aloe and pineapple are both monocots; aloe's succulent look is convergent."),
("P10", "chili", [("tomato",0),("mustard",1),("black_pepper",2)], "plants", "Chili peppers are nightshades, like tomatoes. Black pepper is unrelated: it belongs to the magnoliids (Piperaceae), outside the eudicots that include both chili and mustard."),
("P11", "bamboo", [("rice",0),("palm",1),("oak",2)], "plants", "Bamboo is a grass (family Poaceae), like rice and wheat. Palms are other monocots. Oaks are eudicots."),
]
